def conq_map(w,h,cap,labels):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w/2,30,'خلفائے راشدین کی فتوحات',17,'middle',700)
    b+='<path d="M60 220 Q120 140 220 150 Q320 130 390 190 Q410 270 370 340 Q300 400 200 390 Q110 380 60 300Z" fill="#eee" stroke="#555" stroke-width="2"/>'
    b+='<path d="M70 230 Q130 160 220 165 Q310 150 375 200 Q395 270 360 330 Q300 380 205 372 Q120 365 75 295Z" fill="none" stroke="#111" stroke-width="2" stroke-dasharray="8 3 2 3"/>'
    b+='<path d="M90 250 L180 210 L260 230 L340 260" fill="none" stroke="#111" stroke-width="3"/>'
    b+='<g stroke="#111" stroke-width="2"><line x1="140" y1="320" x2="152" y2="332"/><line x1="152" y1="320" x2="140" y2="332"/><line x1="300" y1="300" x2="312" y2="312"/><line x1="312" y1="300" x2="300" y2="312"/></g>'
    for x,y,t in labels: b+=T(x,y,t,12,'middle',700)
    b+='<rect x="20" y="'+str(h-90)+'" width="140" height="70" fill="#fff" stroke="#111"/><line x1="30" y1="'+str(h-72)+'" x2="60" y2="'+str(h-72)+'" stroke="#111" stroke-dasharray="8 3 2 3" stroke-width="2"/><line x1="30" y1="'+str(h-52)+'" x2="60" y2="'+str(h-52)+'" stroke="#111" stroke-width="3"/><text x="40" y="'+str(h-32)+'" font-size="12" fill="#111">× ×</text>'
    b+=T(110,h-69,'سلطنت کی سرحدیں',10,'middle',700)+T(110,h-49,'فوجوں کے راستے',10,'middle',700)+T(110,h-29,'معرکوں کے مقامات',10,'middle',700)
    return svg(w,h,cap,b)
